# Different argument types select different definitions of the same method.
def scale(x : Int32)
  x * 2
end

def scale(x : Float64)
  x * 0.5
end

a = scale(21)
b = scale(3.0)
{a, b}

class Restricted
  @value : Int32

  def initialize(@value)
  end

  def conditional(value)
    if ARGC_UNSAFE > 0
      @value = value
    end
  end

  def reassigned(value)
    value = 9
    @value = value
  end

  def value
    @value
  end
end

item = Restricted.new(3)
item.conditional(4)
item.reassigned(5)
puts item.value

macro repeated(enabled)
  {% if enabled %}
    {% for value, index in [2, 4, 6] %}
      puts {{value}} + {{index}}
    {% end %}
  {% else %}
    puts 0
  {% end %}
end

repeated(true)
